-- CulinaLink Texas production PostgreSQL reference schema. AppDeploy runtime uses its managed database; this schema is the dedicated PostgreSQL migration target.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE account_status AS ENUM ('CREATED','ACTIVE','RESTRICTED','SUSPENDED','CLOSED');
CREATE TYPE verification_status AS ENUM ('PENDING','VERIFIED','REJECTED','EXPIRED','REVOKED','DEMO_ONLY');
CREATE TYPE booking_status AS ENUM ('DRAFT','COMPLIANCE_REVIEW','REQUESTED','CONFIRMED','IN_PROGRESS','COMPLETED','CANCELLED','DISPUTED','DEMO_REQUEST');
CREATE TYPE pricing_model AS ENUM ('HOURLY','FIXED','PER_PERSON','PER_MEAL','PER_SHIFT','CUSTOM_QUOTE');
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,phone text,status account_status NOT NULL DEFAULT 'CREATED',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid UNIQUE NOT NULL REFERENCES users(id),display_name text,saved_preferences jsonb NOT NULL DEFAULT '{}',created_at timestamptz DEFAULT now());
CREATE TABLE business_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid UNIQUE NOT NULL REFERENCES users(id),legal_name text,display_name text,billing_email text,created_at timestamptz DEFAULT now());
CREATE TABLE professional_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid UNIQUE NOT NULL REFERENCES users(id),display_name text NOT NULL,professional_title text NOT NULL,business_name text,bio text,city text NOT NULL,state char(2) NOT NULL DEFAULT 'TX',latitude numeric(9,6),longitude numeric(9,6),service_radius_miles integer NOT NULL DEFAULT 35,hourly_rate numeric(10,2),availability text NOT NULL DEFAULT 'SCHEDULED',credential_status verification_status NOT NULL DEFAULT 'PENDING',rating_average numeric(3,2) NOT NULL DEFAULT 0,review_count integer NOT NULL DEFAULT 0,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE service_categories(id bigserial PRIMARY KEY,slug text UNIQUE NOT NULL,name text NOT NULL,active boolean NOT NULL DEFAULT true);CREATE TABLE specialties(id bigserial PRIMARY KEY,name text UNIQUE NOT NULL);CREATE TABLE professional_specialties(professional_id uuid REFERENCES professional_profiles(id) ON DELETE CASCADE,specialty_id bigint REFERENCES specialties(id),PRIMARY KEY(professional_id,specialty_id));
CREATE TABLE professional_services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),professional_id uuid NOT NULL REFERENCES professional_profiles(id) ON DELETE CASCADE,category_id bigint REFERENCES service_categories(id),name text NOT NULL,description text,pricing pricing_model NOT NULL,base_price numeric(10,2),duration_minutes integer,min_guests integer,max_guests integer,instant_book boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true);
CREATE TABLE availability_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),professional_id uuid NOT NULL REFERENCES professional_profiles(id) ON DELETE CASCADE,day_of_week smallint CHECK(day_of_week BETWEEN 0 AND 6),starts_at time,ends_at time,active boolean DEFAULT true);CREATE TABLE availability_exceptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),professional_id uuid NOT NULL REFERENCES professional_profiles(id) ON DELETE CASCADE,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,available boolean NOT NULL,reason text);
CREATE TABLE credentials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),professional_id uuid REFERENCES professional_profiles(id) ON DELETE CASCADE,type text NOT NULL,provider text,certificate_number text,issue_date date,expiration_date date,status verification_status NOT NULL DEFAULT 'PENDING',verified_at timestamptz,verified_by uuid,verification_source text,document_key text,created_at timestamptz DEFAULT now());CREATE TABLE permits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),professional_id uuid REFERENCES professional_profiles(id) ON DELETE CASCADE,facility_id uuid,type text NOT NULL,jurisdiction text,permit_number text,issue_date date,expiration_date date,status verification_status NOT NULL DEFAULT 'PENDING',document_key text,created_at timestamptz DEFAULT now());
CREATE TABLE facilities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,facility_type text NOT NULL,address jsonb NOT NULL,latitude numeric(9,6),longitude numeric(9,6),jurisdiction text,created_at timestamptz DEFAULT now());ALTER TABLE permits ADD CONSTRAINT fk_permit_facility FOREIGN KEY(facility_id) REFERENCES facilities(id);
CREATE TABLE portfolio_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),professional_id uuid NOT NULL REFERENCES professional_profiles(id) ON DELETE CASCADE,title text,dish_name text,description text,media_key text NOT NULL,is_signature_dish boolean NOT NULL DEFAULT false,allergen_tags text[] NOT NULL DEFAULT '{}',dietary_tags text[] NOT NULL DEFAULT '{}',created_at timestamptz DEFAULT now());
CREATE TABLE gigs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),seeker_user_id uuid NOT NULL REFERENCES users(id),title text NOT NULL,service_type text NOT NULL,city text NOT NULL,service_latitude numeric(9,6),service_longitude numeric(9,6),starts_at timestamptz,ends_at timestamptz,budget numeric(10,2),status text NOT NULL DEFAULT 'OPEN',requirements jsonb NOT NULL DEFAULT '{}',created_at timestamptz DEFAULT now());CREATE TABLE gig_applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),gig_id uuid NOT NULL REFERENCES gigs(id) ON DELETE CASCADE,professional_id uuid NOT NULL REFERENCES professional_profiles(id),proposed_rate numeric(10,2),message text,status text NOT NULL DEFAULT 'APPLIED',created_at timestamptz DEFAULT now(),UNIQUE(gig_id,professional_id));
CREATE TABLE bookings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),seeker_user_id uuid NOT NULL REFERENCES users(id),professional_id uuid REFERENCES professional_profiles(id),gig_id uuid REFERENCES gigs(id),service_type text NOT NULL,starts_at timestamptz,ends_at timestamptz,status booking_status NOT NULL DEFAULT 'DRAFT',regulatory_class text,compliance_decision text,service_address jsonb,subtotal numeric(10,2) NOT NULL DEFAULT 0,tax numeric(10,2) NOT NULL DEFAULT 0,platform_fee numeric(10,2) NOT NULL DEFAULT 0,tip numeric(10,2) NOT NULL DEFAULT 0,total numeric(10,2) NOT NULL DEFAULT 0,created_at timestamptz DEFAULT now());CREATE TABLE booking_status_history(id bigserial PRIMARY KEY,booking_id uuid NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,from_status booking_status,to_status booking_status NOT NULL,actor_user_id uuid REFERENCES users(id),reason text,created_at timestamptz DEFAULT now());
CREATE TABLE conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid REFERENCES bookings(id),gig_id uuid REFERENCES gigs(id),created_at timestamptz DEFAULT now());CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,sender_user_id uuid NOT NULL REFERENCES users(id),body text,attachment_key text,created_at timestamptz DEFAULT now());
CREATE TABLE payment_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES bookings(id),processor text,processor_reference text,status text NOT NULL,amount numeric(12,2) NOT NULL,currency char(3) NOT NULL DEFAULT 'USD',created_at timestamptz DEFAULT now());CREATE TABLE payout_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),professional_id uuid NOT NULL REFERENCES professional_profiles(id),processor_reference text,status text NOT NULL,amount numeric(12,2) NOT NULL,currency char(3) NOT NULL DEFAULT 'USD',created_at timestamptz DEFAULT now());
CREATE TABLE ledger_accounts(id bigserial PRIMARY KEY,code text UNIQUE NOT NULL,name text NOT NULL,account_type text NOT NULL);CREATE TABLE ledger_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid REFERENCES bookings(id),external_reference text,created_at timestamptz DEFAULT now());CREATE TABLE ledger_entries(id bigserial PRIMARY KEY,transaction_id uuid NOT NULL REFERENCES ledger_transactions(id),account_id bigint NOT NULL REFERENCES ledger_accounts(id),direction text NOT NULL CHECK(direction IN ('DEBIT','CREDIT')),amount numeric(14,2) NOT NULL CHECK(amount>=0),created_at timestamptz DEFAULT now());
CREATE TABLE tax_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid UNIQUE NOT NULL REFERENCES users(id),tax_classification text,tin_token text,w9_signed_at timestamptz,backup_withholding boolean NOT NULL DEFAULT false,created_at timestamptz DEFAULT now());CREATE TABLE tax_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),tax_year integer NOT NULL,document_type text NOT NULL,status text NOT NULL,document_key text,created_at timestamptz DEFAULT now());
CREATE TABLE reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid UNIQUE NOT NULL REFERENCES bookings(id),reviewer_user_id uuid NOT NULL REFERENCES users(id),professional_id uuid NOT NULL REFERENCES professional_profiles(id),rating smallint CHECK(rating BETWEEN 1 AND 5),body text,created_at timestamptz DEFAULT now());
CREATE TABLE incidents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid REFERENCES bookings(id),reporter_user_id uuid REFERENCES users(id),category text NOT NULL,severity text,status text NOT NULL DEFAULT 'OPEN',details text,created_at timestamptz DEFAULT now());CREATE TABLE audit_log(id bigserial PRIMARY KEY,actor_user_id uuid,action text NOT NULL,resource_type text NOT NULL,resource_id text,reason text,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz DEFAULT now());